SELECT  
  WHERE m.space_id=#{actor.spaceId} AND m.owner_user_id=#{actor.userId} AND m.capability_id=#{connector}
  AND v.version_number<#{before} ORDER BY v.version_number DESC LIMIT #{limit}

mapper.update:
UPDATE pf.capability_version_status SET state='PUBLISHED',revision=revision+1,updated_at=clock_timestamp()
  WHERE space_id=#{actor.spaceId} AND owner_user_id=#{actor.userId} AND capability_id=#{version.connectorId}
   AND version_id=#{version.versionId} AND state='DRAFT' AND revision=#{version.revision}
